solution:
def get_price(prices, name):
    return prices.get(name, 0)


def set_price(prices, name, value):
    prices[name] = value
    return prices


def remove_price(prices, name):
    prices.pop(name, None)
    return prices


def has_item(prices, name):
    return name in prices

