def two_dp(x):
    return f"{x:.2f}"


def with_commas(n):
    return f"{n:,}"


def pad_left(s, width):
    return f"{s:>{width}}"

def pick(value, default):
    if value is None:
        return default
    return value

def make_dict(keys, values):
    return dict(zip(keys, values))


def invert(d):
    return {v: k for k, v in d.items()}

