    ...

solution:
def swap(a, b):
    a, b = b, a
    return a, b


def split_first(xs):
    first, *rest = xs
    return first, rest


def min_max(xs):
    return min(xs), max(xs)

def number_lines(lines):
    out = []
    for i, line in enumerate(lines, 1):
        out.append(f"{i}. {line}")
    return out

tests:
check_eq("正常转换", lambda: safe_int("42", 0), 42)
check_eq("转不了用默认值", lambda: safe_int("abc", -1), -1)
check_eq("带空格也能转", lambda: safe_int(" 7 ", 0), 7)

@case("TypeError 不该被吞掉")
def _():
    try:
        safe_int(None, 0)
    except TypeError:
        return
    assert False, "except 只该捕获 ValueError，不要捕获所有异常"

solution:
def safe_int(s, default):
    try:
        return int(s)
    except ValueError:
        return default

starter:
class Tally:
    def __init__(self):
        ...

    def add(self, n):
        ...

    def total(self):
        ...

tests:
@case("初始为 0")
def _():
    t = Tally()
    assert t.total() == 0, "初始计数应该是 0"

@case("add 会累加")
def _():
    t = Tally()
    t.add(3)
    t.add(4)
    assert t.total() == 7, "3 + 4 应该是 7"

@case("可以加负数")
def _():
    t = Tally()
    t.add(10)
    t.add(-4)
    assert t.total() == 6, "10 - 4 应该是 6"

@case("两个实例互不影响")
def _():
    a = Tally()
    b = Tally()
    a.add(5)
    assert b.total() == 0, "b 不该受 a 影响"

solution:
class Tally:
    def __init__(self):
        self.count = 0

    def add(self, n):
        self.count += n

    def total(self):
        return self.count

def by_score_desc(rows):
    return sorted(rows, key=lambda r: r["score"], reverse=True)


def neg_key_desc(rows):
    return sorted(rows, key=lambda r: -r["score"])
